(() => {'use strict';if(!window.PTAPP)throw Error('PTAPP kernel mancante');window.addEventListener('error',e=>{try{window.PTAPP.api.techLog(window.PTAPP.state.boot?.uid,'error','runtime',e.message,{file:e.filename,line:e.lineno})}catch{}});window.addEventListener('unhandledrejection',e=>{try{window.PTAPP.api.techLog(window.PTAPP.state.boot?.uid,'error','promise',String(e.reason?.message||e.reason))}catch{}});if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});window.PTAPP.start();})();